import{_ as d,o as r,c as e,ag as a}from"./chunks/framework.DUTPmUpA.js";const h="/_assets/fwxoB5H.6woL48s2.png",o="/_assets/qa2KLoV.DO9GsGjS.png",b="/_assets/RBJadLc.IqdUQ8q4.png",s="/_assets/AZNq6lw.B9YdfanG.png",p="/_assets/X50ysJh.QlqsdpQa.png",n="/_assets/Oh5BbNQ.B6vcJ0fS.png",i="/_assets/cG34Wwj.rybCVLe3.png",l="/_assets/TPtr49u.DvdtIqF9.png",c="/_assets/qwqaa5l.DGJMeCzW.png",m="/_assets/2QciUbK.DhchAV2L.png",y="/_assets/ERIr5ld.aEXgP4P5.png",u="/_assets/ymA3yUU.Ccog7PrH.png",q=JSON.parse('{"title":"Частица волны хаоса","description":"","frontmatter":{"title":"Частица волны хаоса","author":"kritth","steamId":"76561198055627364","date":"05.02.2015"},"headers":[],"relativePath":"assets/particles/chaos-wave-particle.md","filePath":"assets/particles/chaos-wave-particle.md"}'),_={name:"assets/particles/chaos-wave-particle.md"};function g(x,t,f,P,R,v){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="частица-волны-хаоса" tabindex="-1">Частица волны хаоса <a class="header-anchor" href="#частица-волны-хаоса" aria-label="Permalink to &quot;Частица волны хаоса&quot;">​</a></h1><h1>Введение</h1><p> Это взято из проекта, над которым я сейчас работаю. Основная идея этой частицы Система заключалась в том, что этот снаряд представляет собой циклон/торнадо по оси xy, движущийся вперед с определенной количество скорости. Если у вас нет каких-либо основ работы с редактором частиц, перейдите по ссылке <a href="particle-basics"> сначала по этой ссылке </a>. Прежде чем читать дальше, вот готовый продукт. </p><img src="'+h+'"><p> Не беспокойтесь слишком сильно о модели статуи, я поместил ее сюда просто для того, чтобы перед этим проверить привязку к высоте. портирование на саму карту. Есть много способов подойти к этому, но вот как я подхожу к этому. </p> ``` lua Wave - Render sprites - Lifespan decay - Movement basic - Remap control point to velocity (CP1) - Rotation orient to 2d direction (Roll) - Rotation from CP forward orientation (Yaw) - Radius scale - Ramp scale linear simple (Yaw) - Ramp scale linear simple (Radius) - Noise vector - Alpha fade out simple - Alpha fade in simple - Position within sphere random - Color random - Sequence random - Rotation random - Remap control point to scalar (Radius, CP2) - Position modify offset random - Remap control point to scalar (Life Duration, CP3) Electric charge - Render sprites - Movement basic - Radius scale - Lifespan Decay - Alpha fade and decay - Lifetime random - Color random - Rotation random - Sequence random - Position from parent particles - Remap control point to scalar (Radius, CP2) - Alpha random - Position modify offset random - Emit continuously Ground (optional) - Render sprites - Remap control point to velocity (CP1) - Lifespan decay - Movement basic - Radius scale - Alpha fade and decay - Movement place on ground - Position within sphere random - Color random - Remap control point to scalar (Life Duration, CP3) - Remap control point to scalar (Radius, CP2) - Alpha random - Emit continuously ``` <h1>Часть первая: Волновая частица</h1><p>Теперь давайте начнем создавать эту систему частиц.</p> - Откройте редактор частиц и создайте новую частицу. <br> — Добавьте <b> «Рендеринг спрайтов» </b> в Renderer. <br> — Добавьте <b> «Непрерывное излучение» </b> в Emitter. <br> — Добавьте <b> «Lifespan Decay» </b> в Оператор. <p> Пока не беспокойтесь слишком сильно о количестве частиц. Это можно будет отрегулировать позже, прежде чем вы на самом деле закончить эту систему частиц. Давайте изменим значение спрайтов Render на: </p><h4>Рендеринг спрайтов</h4> | Поле | Значение | | ---------------- | ---------------------------------------- | | текстура | материалы/частица/джаггернаут/juggernaut_blade_fury.vtex | | тип ориентации | Мир-Z выровнять | <p> Поскольку эта текстура является текстурой последовательности, я хочу поочередно использовать каждую последовательность. Это может быть сделано следующим образом: </p> - Добавьте <b> «Случайная последовательность» </b> в инициализатор. <p> Теперь давайте настроим нужную нам последовательность. Поскольку это циклон/торнадо с пространством посередине, мы возможно, вам понадобится что-то похожее на последовательность с №3 по №6. Итак, мы меняем следующие значения: </p><h4>Случайная последовательность</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>последовательность мин</td><td>3</td></tr><tr><td>последовательность макс</td><td>6</td></tr></tbody></table><p>Теперь пришло время разместить эту частицу где-нибудь. </p>- Добавить <b> &quot;Положение внутри сферы случайно&quot; </b> в Инициализаторе. <p> Нам не нужно здесь ничего менять, поскольку это всего лишь ориентир для эмиттера. Теперь ваш частица должна выглядеть так. </p><img src="'+o+'"><p> Ну, он не должен так лежать на полу. Теперь мы хотим повернуть его в направлении с чем оно должно столкнуться. Но прежде чем мы доберемся до этого, нам нужно сначала кое-что настроить. </p> - Добавьте <b> «Базовое движение» </b> в инициализатор. <br> — Добавьте <b> «Переназначить контрольную точку на скорость» </b> в инициализаторе. (Контрольная точка по умолчанию будет 1) <p> Я оставлю эти две функции по умолчанию, так как мне не нужно ничего особенного в скорости. эта система. Теперь, если мы настроим контрольную точку №1 с правой стороны, вы сможете свободно настраивать ее. скорость, как будто это контрольная точка в игре, поэтому вы можете сразу увидеть результат. Моя частица теперь движется, но смотрит вверх, а я этого не хочу. Давайте повернем нашу частицу следующим образом: функции. </p> - Добавьте <b> «Ориентация вращения в 2-м направлении» </b> в Операторе. <br> — добавить <b> «Вращение от КП вперед» </b> в Операторе. <p>Со следующими значениями: </p><h4>Поворот в двухмерном направлении</h4> | Поле | Значение | | --------------- | ----- | | смещение вращения | 90,0 | | поле вращения | Ролл | <h4>Вращение от CP вперед </h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>номер контрольной точки</td><td>1</td></tr><tr><td>поле вращения</td><td>рыскание</td></tr><tr><td>смещение вращения</td><td>45,0</td></tr></tbody></table><p> Эти две функции автоматически настроят ваш спрайт так, чтобы он смотрел в направлении движения. все время. Я решил не использовать 90,0 во второй функции, потому что под углом 90 градусов ваша частица будет их очень трудно увидеть сверху, поэтому я немного их опускаю. Теперь вы должны увидеть результат, например это. </p><img src="'+b+'"><p> Теперь основные функции готовы, я настрою внешний вид частицы с помощью следующей функции. </p> - Добавьте <b> «Случайный цвет» </b> в инициализатор. <br> — добавить <b> «Случайное вращение» </b> в инициализатор. <br> — добавить <b> «Случайное смещение изменения позиции» </b> в инициализаторе. <p> Теперь измените цвет на тот, который вам нравится, оставьте вращение случайным и отрегулируйте третий функционировать следующим образом: </p><h4>Смещение изменения позиции случайное</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>смещение мин</td><td>0,0 0,0 100,0</td></tr><tr><td>смещение макс</td><td>0,0 0,0 100,0</td></tr></tbody></table><p> Это сделано для того, чтобы наши частицы начинались в воздухе, а не на земле. Вы можете потянуть эталонную модель вверх, чтобы отрегулировать высоту по своему усмотрению. </p><p>Теперь, когда все готово, мы начнем назначать остальные контрольные точки следующим образом: </p> — Добавить «Переназначить контрольную точку на скаляр» в инициализаторе. <br> — добавить «Переназначить контрольную точку на скаляр» в инициализаторе. (Да дважды) <p>И измените значение следующим образом.</p><h4>Переназначить контрольную точку скаляру #1</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>входной номер контрольной точки</td><td>2</td></tr><tr><td>поле вывода</td><td>Радиус</td></tr><tr><td>входной минимум</td><td>0,0</td></tr><tr><td>входной максимум</td><td>9999,0</td></tr><tr><td>минимум вывода</td><td>0,0</td></tr><tr><td>максимальный выход</td><td>9999,0</td></tr></tbody></table><h4>Переназначить контрольную точку скаляру #2</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>входной номер контрольной точки</td><td>3</td></tr><tr><td>поле вывода</td><td>Продолжительность жизни</td></tr><tr><td>входной минимум</td><td>0,0</td></tr><tr><td>входной максимум</td><td>10,0</td></tr><tr><td>минимум вывода</td><td>0,0</td></tr><tr><td>максимальный выход</td><td>10,0</td></tr></tbody></table><p>Теперь поместите эти значения в контрольные точки справа.</p><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>Контрольная точка №1</td><td>1000 0 0</td></tr><tr><td>Контрольная точка №2</td><td>300 0 0</td></tr><tr><td>Контрольная точка №3</td><td>3 0 0</td></tr></tbody></table><p>Вы должны увидеть что-то вроде этого.</p><img src="'+s+'"><p> Теперь это все инициализаторы, которые вам нужны, давайте теперь настроим детали, пока наши частицы путешествую в операторе. </p><p> Поскольку я чувствую, что торнадо должен расти по мере своего развития и должен постепенно исчезать. эффект, я добавляю в систему следующие функции. </p> - Добавьте <b> «Шкала радиуса» </b> в Операторе. <br> — Добавьте <b> «Простое затухание альфа-сигнала» </b> в Операторе. <br> - Добавьте <b> «Альфа-фейд в простом» </b> в Операторе. <p>Отрегулируйте эти значения по своему усмотрению. Я оставил их по умолчанию, кроме одного: </p>. <h4>Шкала радиуса</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>начальная шкала радиуса</td><td>0,0</td></tr></tbody></table><p> Теперь ваша частица должна выглядеть так. (Я просто настраиваю цвет случайным образом, поэтому он будет выглядеть немного отличается от предыдущего изображения.) </p><img src="'+p+'"><p> Поскольку это своего рода энергетическая волна, я хочу добавить в систему ощущение нестабильности. Поэтому я добавляю эти функции. </p> - Добавьте <b> «Скалярный линейный простой пандус» </b> в Оператор. <br> — Добавьте <b> «скалярный линейный простой пандус» </b> в Оператор. (Да дважды) <br> — Добавьте <b> «Вектор шума» </b> в Оператор. <p>Измените его значение на следующее: </p><h4>Скалярное линейное простое линейное изменение #1</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>скорость рампы</td><td>15,0</td></tr><tr><td>поле рампы</td><td>рыскание</td></tr></tbody></table><h4>Скалярное линейное простое линейное изменение #2</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>скорость рампы</td><td>2500</td></tr><tr><td>время окончания</td><td>9999,0</td></tr><tr><td>поле рампы</td><td>Радиус</td></tr></tbody></table><h4>Вектор шума</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>поле вывода</td><td>Позиция</td></tr><tr><td>минимум вывода</td><td>-100,0 -100,0 -100,0</td></tr><tr><td>максимальный выход</td><td>100,0 100,0 100,0</td></tr><tr><td>добавка</td><td>правда</td></tr></tbody></table><p>Теперь ваша волновая частица готова. Это должно выглядеть примерно так: </p><img src="'+n+'"><p> То, что я сказал о «готово», на самом деле ложь. Вам все равно нужно отрегулировать количество частиц. Мой Совет заключается в том, чтобы поддерживать минимальное количество, соответствующее целям вашей системы. В настоящее время количество частиц всегда должно быть около 300, и это нехорошо для общей производительности. Поскольку мои частицы будут использоваться как снаряд, мне не нужно большое количество частиц. Чтобы уменьшите это, я изменю следующую настройку. </p><h4>Базовые свойства</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>максимум частиц</td><td>60</td></tr></tbody></table><h4>Излучать непрерывно</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>продолжительность эмиссии</td><td>2.0</td></tr><tr><td>уровень выбросов</td><td>30,0</td></tr></tbody></table><p> При этом количество частиц всегда должно быть ниже 60, поскольку я хочу, чтобы они излучали только в течение 2 секунды, по 30 частиц каждая, а выделенной памяти хватает только на 60 частиц. Теперь ваш базовые волновые частицы готовы. <b>Очень важно, не забудьте сохранить.</b></p><h1>Часть вторая: Частица искры</h1><p> Теперь, когда моя волновая частица работает, я чувствую, что ей нужно что-то вроде электрической искры. в течение срока действия. Однако, поскольку эта частица основана на волновой частице, нам нужно сделать некоторые корректировки волновой частицы. </p> - Создайте новую частицу для статики и сохраните ее. <br> — в волновой частице добавьте вновь созданную частицу в качестве дочерней. <p>Сначала, как обычно, вы хотите начать рендеринг вашего спрайта, эмиттера и затухания. </p>- Добавить <b> «Рендеринг спрайтов» </b> в Renderer. <br> — Добавьте <b> «Непрерывное излучение» </b> в Emitter. <br> — Добавить <b> «Снижение срока службы» </b> в Операторе. <p>Измените текстуру спрайтов рендеринга на </p>. ``` materials/particle/electrical_arc_smooth/electrical_arc_smooth.vtex ``` <p> Теперь подумайте о настоящей электрической искре: она должна быть быстрой, красочной и выглядеть по-разному. время и немного прозрачности. Исходя из этих идей, я добавляю следующие функции. </p> - Добавьте <b> «Случайный случай на всю жизнь» </b> в инициализатор. <br> — добавить <b> «Случайный цвет» </b> в инициализатор. <br> — добавить <b> «Случайное вращение» </b> в инициализатор. <br> — добавить <b> «Случайная последовательность» </b> в инициализатор. <br> — добавить <b> «Альфа-случайный» </b> в инициализатор. <p> Отрегулируйте цвет соответствующим образом для параметра «Случайный цвет» и оставьте значение «Вращение случайным» по умолчанию. Для других функции, измените значение на следующее. </p><h4>Случайное время жизни</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>срок службы мин</td><td>0,03</td></tr><tr><td>максимальный срок службы</td><td>0,07</td></tr></tbody></table><h4>Случайная последовательность</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>последовательность мин</td><td>0</td></tr><tr><td>последовательность макс</td><td>3</td></tr></tbody></table><h4>Альфа-случайный</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>альфа мин</td><td>150</td></tr><tr><td>альфа макс</td><td>175</td></tr></tbody></table><p>Теперь у вас должно получиться что-то похожее на это.</p><img src="'+i+'"><p> Когда это будет сделано, мы хотим соответствующим образом изменить наш радиус, поскольку у нас уже есть контрольная точка в волне. частицы и заставляют искру рассеиваться от центра. </p> - Добавьте <b> «Переназначить контрольную точку на скаляр» </b> в инициализаторе. <br> — добавить <b> «Случайное смещение изменения позиции» </b> в инициализаторе. <p>Теперь мы устанавливаем следующее значение: </p><h4>Переназначить контрольную точку скалярной </h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>входной номер контрольной точки</td><td>2</td></tr><tr><td>поле вывода</td><td>Радиус</td></tr><tr><td>входной максимум</td><td>999,0</td></tr><tr><td>максимальный выход</td><td>999,0</td></tr></tbody></table><h4>Смещение изменения позиции случайное</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>смещение мин</td><td>-0,3 -0,3 -0,3</td></tr><tr><td>смещение макс</td><td>0,3 0,3 0,3</td></tr><tr><td>номер контрольной точки</td><td>0</td></tr><tr><td>смещение пропорционально радиусу</td><td>правда</td></tr></tbody></table><p><img src="'+l+'"></p><p> Как видите, теперь наши частицы огромны! Искры должны быть маленькими, поэтому давайте изменим их размер. этим добавим немного больше движения нашим искрам, а также добавим немного затухания к нашим искрам. частица. </p> - Добавьте <b> «Базовое движение» </b> в Операторе. <br> — добавьте <b> «Масштаб радиуса» </b> в операторе. <br> — Добавить <b> «Альфа-затухание и затухание» </b> в Операторе. <p>Измените значения следующим образом.</p><h4>Базовое движение</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>гравитация</td><td>0,0 0,0 300,0</td></tr><tr><td>перетащить</td><td>0,05</td></tr></tbody></table><h4>Масштаб радиуса</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>начальная шкала радиуса</td><td>0,07</td></tr><tr><td>конечная шкала радиуса</td><td>0,14</td></tr><tr><td>смещение шкалы</td><td>0,65</td></tr></tbody></table><h4>Альфа-затухание и затухание</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>начать исчезать со временем</td><td>0,0</td></tr><tr><td>конец исчезнет со временем</td><td>0,2</td></tr><tr><td>время начала постепенного исчезновения</td><td>0,4</td></tr><tr><td>время окончания исчезновения</td><td>1.0</td></tr><tr><td>начать альфу</td><td>0,0</td></tr><tr><td>конец альфа</td><td>0,0</td></tr></tbody></table><p>Теперь ваша искра должна выглядеть примерно так.</p><img src="'+c+'"><p>С волновыми частицами это выглядит так.</p><img src="'+m+'"><p>Теперь мы хотим, чтобы искра следовала за волной, мы добавляем эту функцию к частице искры. </p>-Добавить <b> «Позиция родительских частиц» </b> в инициализаторе. <p> Оставьте значение по умолчанию, но вы можете настроить его по своему вкусу. Теперь мы почти закончили, мы необходимо уменьшить количество частиц в системе. Измените значения следующей функции. </p><h4>Базовые свойства</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>максимум частиц</td><td>64</td></tr></tbody></table><h4>Излучать непрерывно</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>продолжительность эмиссии</td><td>4.0</td></tr><tr><td>уровень выбросов</td><td>200,0</td></tr></tbody></table><p>Теперь вы должны увидеть в волновой частице что-то вроде следующего. </p><img src="'+y+'"><p>На этом ваша искровая частица готова. Не стесняйтесь корректировать значение по своему вкусу.</p><h1>Часть третья: Наземная частица (дополнительно) </h1><p> Вы можете задаться вопросом, почему я перечисляю эту часть как необязательную. Это не является обязательным требованием, так как на самом деле это не так. заставить вас увидеть, что происходит в редакторе частиц. Когда вы заходите в игру, если место имеет светлый фон, будет очень трудно увидеть яркую цветную частицу. С этим наземная частица, я обычно размещаю темную частицу под волновой частицей, чтобы сделать ее более виден пользователю. </p><p> Эта частица заимствует большую часть ценности у волновой частицы, за исключением одной функции. Я перечислю все функции и их скорректированное значение ниже. Более подробную информацию о каждой из функций см. вернуться к чтению раздела о волновых частицах. </p><h4>Базовые свойства</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>максимум частиц</td><td>60,0</td></tr></tbody></table><h4>Renderer: рендеринг спрайтов</h4> | Поле | Значение | | ---------------- | ---------------------------------------- | | тип ориентации | Мир-Z Выровнять | | текстура | материалы/частица/грязь/ground_decay/ground_decay01.vtex | <h4>Operator: переназначить контрольную точку на скорость</h4><h4>Оператор: Снижение срока службы</h4><h4>Оператор: Базовое движение</h4><h4>Оператор: Масштаб радиуса</h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>начальная шкала радиуса</td><td>0,2</td></tr><tr><td>конечная шкала радиуса</td><td>1,2</td></tr></tbody></table><h4>Оператор: Альфа-затухание и затухание</h4><h4>Оператор: Место движения на земле</h4><h4>Инициализатор: случайное положение внутри сферы</h4><h4>Инициализатор: случайный цвет</h4><h4>Initializer: переназначить контрольную точку на скалярную </h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>входной номер контрольной точки</td><td>3</td></tr><tr><td>поле вывода</td><td>Продолжительность жизни</td></tr><tr><td>входной максимум</td><td>10,0</td></tr><tr><td>максимальный выход</td><td>10,0</td></tr></tbody></table><h4>Initializer: переназначить контрольную точку на скалярную </h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>входной номер контрольной точки</td><td>2</td></tr><tr><td>поле вывода</td><td>Радиус</td></tr><tr><td>входной максимум</td><td>9999,0</td></tr><tr><td>максимальный выход</td><td>9999,0</td></tr></tbody></table><h4>Инициализатор: альфа-случайный </h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>альфа мин</td><td>30</td></tr><tr><td>альфа макс</td><td>50</td></tr></tbody></table><h4>Инициализатор: непрерывно генерировать </h4><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>продолжительность эмиссии</td><td>2.0</td></tr><tr><td>уровень выбросов</td><td>30,0</td></tr></tbody></table><p><b>Не забудьте сохранить файл.</b> Теперь все готово, давайте объединим все работы вместе. </p><h1>Часть четвертая: Доработка системы</h1><p>Наша система почти закончена. Теперь мы собираемся добавить несколько слоев волны.</p> - Откройте свою волновую частицу. <br> - Уберите детей. <br> - Сохраните как новую частицу для внешнего слоя (у него не должно быть дочерних элементов). <br> — снова сохраните как новую частицу для контура (у нее также не должно быть дочерних элементов). <p>Эти три слоя будут вести себя одинаково, между каждым слоем есть только три различия.</p> 1. Радиус <br> 2. Цвет <br> 3. Порядковый номер <p>Давайте установим наши 3 слоя (или больше, если хотите) следующим образом. </p><p> Для самого внутреннего слоя, нашего основного слоя, отрегулируйте цвет, чтобы он стал очень ярким, <b>конечный масштаб радиуса </b> в <b>Масштаб радиуса </b> равен 0,6, а для <b>sequence min/max</b> установлены значения 7 и 8. </p><p> Для внешнего слоя, второго слоя, отрегулируйте цвет между очень ярким цветом и черным. иметь конечный масштаб <b>radius</b> в <b>Масштаб радиуса </b> как 1,0, а для <b>sequence min/max</b> установлено значение 7 и 8. </p><p> Для слоя контура, последнего слоя, настройте цвет на черный и установите конечный масштаб радиуса <b></b>. в <b>Масштаб радиуса </b> равен 1,2. </p><p> Теперь мы объединяем два внешних слоя в наш основной слой, добавляя дочерние элементы. Ваш экран должен выглядеть вот так. </p><img src="'+u+`"><p> Если у вас нет частиц земли, на этом пора закончить. Однако, если у вас есть заземление частица тогда: </p> - Создать новую частицу. <br> - Добавить частицу земли в качестве дочернего элемента. <br> — добавить волновую частицу как дочернюю. <p> Важно, чтобы наземная частица находилась над волновой частицей. Это порядок, в котором ваш Частица будет визуализирована. Если наземная частица находится ниже волновой частицы, она будет сверху волны. частица, а это не то, чего мы хотим. </p><h1>Реализовать в игре</h1><p> Теперь, когда частица готова, нам нужно использовать ее в игре. Обратите внимание, что эта частица не полностью совместим со снарядом. Поэтому имитируем снаряд следующим образом: </p><h4>KV npc_abilities_custom.txt</h4><p>В способности, которую вы хотите использовать, вставьте эти строки.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;precache&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;particle&quot;		&quot;particles/custom/tutorial/cyclone.vpcf&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Теперь, когда вы хотите запустить частицы в Lua, вы делаете следующее</p> \`\`\` lua local info = { ... EffectName = &quot;&quot;, vVelocity = keys.caster:GetForwardVector() * ProjectileSpeed, fDistance = Distance, fStartRadius = Radius, fEndRadius = Radius, ... } <p>local projectile = ProjectileManager:CreateLinearProjectile(info)</p><p>-- Create particle local tornadoFxIndex = ParticleManager:CreateParticle( &quot;particles/custom/tutorial/cyclone.vpcf&quot;, PATTACH_CUSTOMORIGIN, caster ) ParticleManager:SetParticleControl( tornadoFxIndex, 0, keys.caster:GetAbsOrigin() ) ParticleManager:SetParticleControl( tornadoFxIndex, 1, keys.caster:GetForwardVector() * ProjectileSpeed ) ParticleManager:SetParticleControl( tornadoFxIndex, 2, Vector( Radius, 0, 0 ) ) ParticleManager:SetParticleControl( tornadoFxIndex, 3, Vector( Distance / ProjectileSpeed, 0, 0 ) )</p><p>Timers:CreateTimer( 6.0, function() ParticleManager:DestroyParticle( tornadoFxIndex, false ) ParticleManager:ReleaseParticleIndex( tornadoFxIndex ) return nil end )</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;p&gt;Когда это реализовано, ваши частицы теперь должны появиться в игре.&lt;/p&gt;</span></span>
<span class="line"><span>&lt;p&gt;На этом завершается мой урок по созданию частиц Волны Хаоса.&lt;/p&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div>`,296)])])}const I=d(_,[["render",g]]);export{q as __pageData,I as default};
